sys_variable_value.value:
(function execute(inputs, outputs) {

var table = [];
var grApproved = new GlideRecord('x_1488662_bases_admission');
grApproved.addActiveQuery();
grApproved.addEncodedQuery('base='+ inputs.base_name);
grApproved.query();

while (grApproved.next()) {
    table.push({
        "Number": grApproved.getValue('number'),
        "OpenedBy": grApproved.getDisplayValue('opened_by'),
        "JobPosition": grApproved.getDisplayValue('job_position')
    });
}

// Convert the array to a nicely formatted JSON string
var output = JSON.stringify(table, null, 2);

    // Set the output to be used in the flow or action
    outputs.result = output;

})(inputs, outputs);

